  // Move and turn as the brain says. Grab and lock come in lesson 3.
  act(move: brain.move, turn: brain.turn, grab: 0, lock: 0)

  if agent.isHider {
    // +1 per second hidden, -1 per second seen.
    reward +1 * dt when agent.hidden
    reward -1 * dt when agent.seen
  } else {
    // Add the seeker's reward here.
  }
}

